type Notice = { msg: string; type: 'ok' | 'err' } | null;
const statusClass = (status: string) => status === 'Confirmed' || status === 'Released' || status === 'Active'
  ? 'bg-emerald-500' : status === 'Pending' || status === 'Pending Confirmation' || status === 'Release In Process'
    ? 'bg-amber-500' : status === 'Cancelled' || status === 'Closed' ? 'bg-slate-500' : 'bg-cyan-500';
const Status = ({ value }: { value: string }) => <span className={`inline-block min-w-20 rounded-sm px-2 py-1 text-center text-[11px] font-semibold text-white ${statusClass(value)}`}>{value}</span>;
const Th = ({ children }: { children?: React.ReactNode }) => <th className="border-r border-slate-200 bg-[#edf0f3] px-2 py-2 text-left text-[11px] font-semibold text-slate-600">{children}</th>;
const Td = ({ children }: { children: React.ReactNode }) => <td className="border-r border-t border-slate-200 px-2 py-2 text-xs text-slate-600">{children}</td>;
const Tab = ({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) => <button onClick={onClick} className={`border-b-2 px-3 py-2 text-xs font-semibold ${active ? 'border-rose-400 text-slate-700' : 'border-transparent text-slate-500'}`}>{children}</button>;
const Field = ({ label, required, children }: { label: string; required?: boolean; children: React.ReactNode }) => <label className="grid grid-cols-[125px_1fr] items-center gap-2 text-xs text-slate-500"><span className="text-right">{label}{required && <b className="text-rose-500"> *</b>}</span>{children}</label>;
type AdditionalCharge = { charge_id: string; charge_line_id: string; charge_type: string; charge_name: string; operand: number; charge: number };
function AdditionalChargesPanel({ charges, onChange }: { charges: AdditionalCharge[]; onChange: (charges: AdditionalCharge[]) => void }) {
  const [editing, setEditing] = useState<string | null>(null);
  const updateOperand = (id: string, value: string) => {
    const operand = Number(value);
    if (!Number.isFinite(operand) || operand < 0) return;
    onChange(charges.map((row) => row.charge_line_id === id ? { ...row, operand } : row));
  };
  return <section className="p-4" aria-label="Additional Charges"><table className="w-full border-collapse"><thead><tr>{['Charge Name', 'Type', 'Amount', 'Charge'].map((heading) => <Th key={heading}>{heading}</Th>)}</tr></thead><tbody>{charges.length ? charges.map((row) => <tr key={row.charge_line_id || row.charge_id} onClick={() => setEditing(row.charge_line_id)} className="cursor-pointer hover:bg-slate-50"><Td>{row.charge_name}</Td><Td>{row.charge_type}</Td><Td>{editing === row.charge_line_id ? <input aria-label={`Amount for ${row.charge_name}`} className="ci max-w-32" type="number" min="0" step="any" autoFocus value={row.operand} onChange={(event) => updateOperand(row.charge_line_id, event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); setEditing(null); } }} onBlur={() => setEditing(null)} /> : Number(row.operand || 0).toFixed(2)}</Td><Td>{Number(row.charge || 0).toFixed(2)}</Td></tr>) : <tr><td colSpan={4} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr>}</tbody></table><p className="mt-3 text-xs text-slate-500">Select a charge row to edit its Amount. Charge Name, Type, and Charge are supplied by the purchase-order charge configuration.</p></section>;
}
function PurchaseOrderUdfPanel({ values, saved, onChange, onSave }: { values: string[]; saved: boolean; onChange: (values: string[]) => void; onSave: () => void }) {
  return <section className="p-4" aria-label="User Defined Fields">
    <div className="grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4">
      {Array.from({ length: 10 }, (_, index) => <Field key={index} label={`PO UDF${index + 1}`}>
        <input aria-label={`PO UDF${index + 1}`} className="ci" maxLength={50} autoComplete="off" value={values[index] || ''} onChange={(event) => { const udf = Array.from({ length: 10 }, (_, i) => values[i] || ''); udf[index] = event.target.value; onChange(udf); }}/>
      </Field>)}
    </div>
    <div className="mt-4 flex justify-end"><Btn variant="warn" disabled={!saved} onClick={onSave}>Save UDF</Btn></div>
  </section>;
}

const TERM_FONTS = ['Arial', 'Comic Sans MS', 'Courier New', 'Georgia', 'Lucida Sans Unicode', 'Tahoma', 'Times New Roman', 'Trebuchet MS', 'Verdana'];
const TERM_SIZES = ['8', '9', '10', '11', '12', '14', '16', '18', '20', '22', '24', '26', '28', '36', '48', '72'];
const TERM_FORMATS = [['Normal', 'p'], ['Heading 1', 'h1'], ['Heading 2', 'h2'], ['Heading 3', 'h3'], ['Heading 4', 'h4'], ['Heading 5', 'h5'], ['Heading 6', 'h6'], ['Formatted', 'pre'], ['Address', 'address'], ['Normal (DIV)', 'div']];
function TermsAndConditionsPanel({ value, onChange, onSave }: { value: string; onChange: (value: string) => void; onSave: () => void }) {
  const editor = useRef<HTMLDivElement>(null); const [source, setSource] = useState(false); const [preview, setPreview] = useState(false); const [showBlocks, setShowBlocks] = useState(false);
  const safeHtml = useMemo(() => DOMPurify.sanitize(value, { USE_PROFILES: { html: true } }), [value]);
  useEffect(() => { if (!source && editor.current && document.activeElement !== editor.current && editor.current.innerHTML !== safeHtml) editor.current.innerHTML = safeHtml; }, [safeHtml, source]);
  const command = (name: string, argument?: string) => { editor.current?.focus(); document.execCommand(name, false, argument); onChange(editor.current?.innerHTML || ''); };
  const button = (title: string, label: string, action: () => void) => <button type="button" title={title} aria-label={title} onClick={action} className="min-w-7 border-r border-slate-300 px-2 py-1 text-[11px] text-slate-700 hover:bg-slate-100">{label}</button>;
  const insertLink = () => { const url = window.prompt('URL'); if (url) command('createLink', url); }; const insertImage = () => { const url = window.prompt('Image URL'); if (url) command('insertImage', url); };
  return <section aria-label="Terms and Conditions" className="p-4"><div className="border border-slate-400 bg-[#f2f2f2]" role="application" aria-label="Rich Text Editor, poTerms">
    <div className="flex flex-wrap border-b border-slate-300" role="toolbar" aria-label="Editor toolbars">
      {button('Source','Source',()=>setSource(!source))}{button('Save','Save',onSave)}{button('New Page','New Page',()=>onChange(''))}{button('Preview','Preview',()=>setPreview(true))}{button('Print','Print',()=>window.print())}
      {button('Undo','↶',()=>command('undo'))}{button('Redo','↷',()=>command('redo'))}{button('Select All','Select All',()=>command('selectAll'))}{button('Bold','B',()=>command('bold'))}{button('Italic','I',()=>command('italic'))}{button('Underline','U',()=>command('underline'))}{button('Strike Through','S',()=>command('strikeThrough'))}{button('Subscript','x₂',()=>command('subscript'))}{button('Superscript','x²',()=>command('superscript'))}{button('Remove Format','Remove Format',()=>command('removeFormat'))}
      {button('Insert/Remove Numbered List','1.',()=>command('insertOrderedList'))}{button('Insert/Remove Bulleted List','•',()=>command('insertUnorderedList'))}{button('Decrease Indent','←',()=>command('outdent'))}{button('Increase Indent','→',()=>command('indent'))}{button('Block Quote','❝',()=>command('formatBlock','blockquote'))}{button('Align Left','Left',()=>command('justifyLeft'))}{button('Center','Center',()=>command('justifyCenter'))}{button('Align Right','Right',()=>command('justifyRight'))}{button('Justify','Justify',()=>command('justifyFull'))}
      {button('Link','Link',insertLink)}{button('Unlink','Unlink',()=>command('unlink'))}{button('Image','Image',insertImage)}{button('Table','Table',()=>command('insertHTML','<table border="1"><tbody><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>'))}{button('Insert Horizontal Line','―',()=>command('insertHorizontalRule'))}{button('Insert Special Character','Ω',()=>command('insertText','Ω'))}{button('Insert Page Break for Printing','Page Break',()=>command('insertHTML','<div style="page-break-after:always"><span style="display:none">&nbsp;</span></div>'))}
      <select aria-label="Paragraph Format" title="Paragraph Format" className="border-0 border-r border-slate-300 bg-white px-1 text-[11px]" defaultValue="" onChange={e=>{if(e.target.value)command('formatBlock',e.target.value);e.target.value=''}}><option value="">Format</option>{TERM_FORMATS.map(([label,tag])=><option key={tag} value={tag}>{label}</option>)}</select>
      <select aria-label="Font Name" title="Font Name" className="border-0 border-r border-slate-300 bg-white px-1 text-[11px]" defaultValue="" onChange={e=>{if(e.target.value)command('fontName',e.target.value);e.target.value=''}}><option value="">Font</option>{TERM_FONTS.map(x=><option key={x}>{x}</option>)}</select>
      <select aria-label="Font Size" title="Font Size" className="border-0 border-r border-slate-300 bg-white px-1 text-[11px]" defaultValue="" onChange={e=>{if(e.target.value)command('fontSize',String(Math.max(1,Math.min(7,Math.ceil((TERM_SIZES.indexOf(e.target.value)+1)/2)))));e.target.value=''}}><option value="">Size</option>{TERM_SIZES.map(x=><option key={x}>{x}</option>)}</select>
      <label className="px-2 py-1 text-[11px]" title="Text Colour">Text <input aria-label="Text Colour" type="color" onChange={e=>command('foreColor',e.target.value)} className="h-5 w-6 align-middle"/></label><label className="px-2 py-1 text-[11px]" title="Background Colour">Background <input aria-label="Background Colour" type="color" onChange={e=>command('hiliteColor',e.target.value)} className="h-5 w-6 align-middle"/></label>{button('Show Blocks','Show Blocks',()=>setShowBlocks(!showBlocks))}{button('About CKEditor 4','About',()=>setPreview(true))}
    </div>
    {source?<textarea aria-label="Terms and Conditions HTML source" className="min-h-52 w-full resize-y bg-white p-3 font-mono text-xs outline-none" value={value} onChange={e=>onChange(e.target.value)}/>:<div ref={editor} role="textbox" aria-label="Terms and Conditions editor" aria-multiline="true" contentEditable suppressContentEditableWarning onPaste={e=>{e.preventDefault();const html=e.clipboardData.getData('text/html');command(html?'insertHTML':'insertText',html?DOMPurify.sanitize(html,{USE_PROFILES:{html:true}}):e.clipboardData.getData('text/plain'));}} onDrop={e=>{e.preventDefault();command('insertText',e.dataTransfer.getData('text/plain'));}} onInput={e=>onChange(e.currentTarget.innerHTML)} className={`min-h-52 resize-y overflow-auto bg-white p-3 text-sm outline-none ${showBlocks?'[&_*]:outline [&_*]:outline-1 [&_*]:outline-dotted [&_*]:outline-slate-300':''}`}/>}<div className="border-t border-slate-300 px-2 py-1 text-[10px] text-slate-500">◢</div>
  </div><textarea id="poTerms" name="poDTO.poTerms" hidden readOnly value={value}/><input id="hiddenPoTerms" name="hiddenPoTerms" type="hidden" value={value}/><Modal title="Preview" open={preview} onClose={()=>setPreview(false)}><article aria-label="Terms and Conditions preview" className="min-h-40" dangerouslySetInnerHTML={{__html:safeHtml}}/><div className="mt-4 text-right"><Btn variant="ghost" onClick={()=>setPreview(false)}>Close</Btn></div></Modal></section>;
}
type PoComment = { comment_date?: string; commentDate?: string; comment_added_by?: string; commentAddedBy?: string; comment_status?: string; commentStatus?: string; view_comments?: string; viewComments?: string };
function CommentHistoryPanel({ value, comments, saved, onChange, onSubmit }: { value: string; comments: PoComment[]; saved: boolean; onChange: (value: string) => void; onSubmit: () => void }) {
  return <section aria-label="Comment History" className="p-4">
    <div className="grid grid-cols-[220px_1fr] items-start gap-3">
      <label htmlFor="comments" className="pt-2 text-right text-xs font-medium text-slate-600">Add Purchase Order Comments</label>
      <textarea id="comments" name="poDTO.comments" aria-label="Add Purchase Order Comments" rows={10} autoComplete="off" className="ci min-h-32" value={value} onChange={event=>onChange(event.target.value)}/>
    </div>
    <div className="mt-2 flex justify-end"><Btn variant="warn" disabled={!saved} onClick={onSubmit}>Submit Comments</Btn></div>
    <fieldset className="mt-3 border border-slate-300 p-3"><legend className="px-2 text-sm font-semibold text-slate-600">Comments</legend>
      {comments.length ? <table id="commentSec" className="w-full text-xs"><tbody>{comments.map((entry,index)=><tr key={`${entry.comment_date||entry.commentDate}-${index}`} className="border-b align-top"><td className="py-2"><input id="commentDate" name="commentDate" type="hidden" value={entry.comment_date||entry.commentDate||''}/><input id="commentAddedBy" name="commentAddedBy" type="hidden" value={entry.comment_added_by||entry.commentAddedBy||''}/><input id="commentStatus" name="commentStatus" type="hidden" value={entry.comment_status||entry.commentStatus||''}/><input id="viewComments" name="viewComments" type="hidden" value={entry.view_comments||entry.viewComments||''}/><div className="grid grid-cols-[45px_150px_65px_1fr_58px_1fr] gap-1"><span>Date :</span><b>{entry.comment_date||entry.commentDate}</b><span>AddedBy :</span><b>{entry.comment_added_by||entry.commentAddedBy}</b><span>Status :</span><b>{entry.comment_status||entry.commentStatus}</b></div><p className="py-2">{entry.view_comments||entry.viewComments}</p></td></tr>)}</tbody></table> : <p id="commentSec" className="text-xs text-slate-600">No Comments to View</p>}
    </fieldset>
  </section>;
}
type PoTagRow = { poTag: string; poTagText: string; poTagStatusText: string; poTagStatus?: string; tagDateText: string; tagDate?: string; taggedByText: string; taggedBy?: string; actionFlag: string; tagType: string };
type PoTagOption = { value: string; text: string };
function PoTagsPanel({ poCode, status, onNotice, onPersist }: { poCode?: string; status: string; onNotice: (notice: Notice) => void; onPersist: (rows: PoTagRow[]) => void }) {
  const [options, setOptions] = useState<PoTagOption[]>([]); const [rows, setRows] = useState<PoTagRow[]>([]); const [selectedTag, setSelectedTag] = useState(''); const [selectedRows, setSelectedRows] = useState<string[]>([]); const [invalid, setInvalid] = useState(false);
  useEffect(() => {
    if (!poCode) return;
    apiGet<any>(`/api/purchase-order-tags?poCode=${encodeURIComponent(poCode)}`).then((result) => {
      setOptions(result.options || []); setRows(result.poTagMaintDto?.poTagRowDTOList || []); setSelectedRows([]);
    }).catch((error) => onNotice({ msg: error.message, type: 'err' }));
  }, [poCode, onNotice]);
  const add = () => {
    if (!selectedTag) { setInvalid(true); onNotice({ msg: 'PO Tags is mandatory.', type: 'err' }); return; }
    const option = options.find((item) => item.value === selectedTag); if (!option) return;
    const existing = rows.find((row) => row.poTag === selectedTag && row.tagType !== 'ATH');
    if (existing) { setRows(rows.map((row) => row === existing && row.actionFlag === 'D' ? { ...row, actionFlag: 'A' } : row)); return; }
    const now = new Date();
    setRows([...rows, { poTag: option.value, poTagText: option.text, poTagStatusText: status, poTagStatus: '', tagDateText: now.toLocaleString('en-GB', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit', hour12:true }).replace(',', '').toUpperCase(), tagDate: '', taggedByText: 'Current User', taggedBy: 'current-user', actionFlag: 'A', tagType: '' }]);
  };
  const remove = () => {
    if (!selectedRows.length) { onNotice({ msg: 'Please select row(s) to delete.', type: 'err' }); return; }
    setRows(rows.flatMap((row) => selectedRows.includes(row.poTag) ? (row.tagType ? [{ ...row, actionFlag: 'D' }] : []) : [row])); setSelectedRows([]);
  };
  const save = async () => {
    if (!poCode) return;
    const changed = rows.filter((row) => row.actionFlag === 'A' || row.actionFlag === 'D');
    if (!changed.length) return;
    try {
      const gridData = changed.map((row) => [row.poTag, row.actionFlag, row.tagType].join('\u0015')).join('\u0015');
      const result = await apiSend<any>('/api/purchase-order-tags', 'POST', { gridData, poCode, siteLoc: '', statusCode: rows[0]?.poTagStatus || '' });
      const persisted = result.poTagMaintDto?.poTagRowDTOList || []; setRows(persisted); setSelectedRows([]); onPersist(persisted); onNotice({ msg: 'PO Tags Saved Successfully.', type: 'ok' });
    } catch (error: any) { onNotice({ msg: error.message, type: 'err' }); }
  };
  return <section id="poTagTab" aria-label="PO Tags" className="p-4"><fieldset className="border border-slate-300 p-3"><div className="grid max-w-md grid-cols-[130px_1fr] items-start gap-2"><label id="poMainForm_pocreate_single_poTags" htmlFor="poTag_select" className="pt-2 text-right text-xs font-medium text-slate-600">PO Tags</label><select name="poTag_select" size={4} id="poTag_select" aria-label="PO Tags" className={`ci h-28 ${invalid?'border-red-500 bg-red-50':''}`} value={selectedTag} onChange={(event)=>{setSelectedTag(event.target.value);setInvalid(false)}}>{options.map((option)=><option key={option.value} value={option.value}>{option.text}</option>)}</select></div><div className="mt-2 flex justify-end gap-1"><button id="poTags_AddButton" type="button" onClick={add} className="rounded-sm bg-sky-700 px-3 py-1 text-xs text-white">Add Tags</button><button id="poTags_SaveButton" type="button" onClick={()=>{void save()}} className="rounded-sm bg-sky-700 px-3 py-1 text-xs text-white">Save Tags</button><button id="poTags_RemoveButton" type="button" onClick={remove} className="rounded-sm bg-sky-700 px-3 py-1 text-xs text-white">Remove Tags</button></div></fieldset><table id="poTags_grid" className="mt-2 w-full border-collapse"><thead><tr><Th><input id="cb_poTags_grid" type="checkbox" aria-label="Select all PO Tags" checked={Boolean(rows.length)&&rows.every((row)=>selectedRows.includes(row.poTag)||row.actionFlag==='D')} onChange={(event)=>setSelectedRows(event.target.checked?rows.filter((row)=>row.actionFlag!=='D').map((row)=>row.poTag):[])}/></Th>{['PO Tag','PO Status When Tagged','Tag Date','Tagged By'].map((heading)=><Th key={heading}>{heading}</Th>)}</tr></thead><tbody>{rows.map((row)=><tr key={`${row.poTag}-${row.tagType}`} className={row.actionFlag==='D'?'bg-red-50 text-slate-400 opacity-60':''}><Td><input type="checkbox" aria-label={`Select ${row.poTagText}`} disabled={row.actionFlag==='D'} checked={selectedRows.includes(row.poTag)} onChange={(event)=>setSelectedRows(event.target.checked?[...selectedRows,row.poTag]:selectedRows.filter((value)=>value!==row.poTag))}/></Td><Td>{row.poTagText}</Td><Td>{row.poTagStatusText}</Td><Td>{row.tagDateText}</Td><Td>{row.taggedByText}</Td></tr>)}</tbody></table></section>;
}
type PoInboundRow = { inboundNo: string; createDate: string; GRNNo: string; asnNumber: string; GRNDate: string; invoiceNo: string; status: string; commonInboundType?: string; expQty?: number|string; rcvQty?: number|string };
function PoInboundPanel({ poCode, onNotice }: { poCode?: string; onNotice: (notice: Notice) => void }) {
  const navigate = useNavigate();
  const [rows, setRows] = useState<PoInboundRow[]>([]);
  useEffect(() => {
    if (!poCode) return;
    apiGet<any>(`/api/purchase-order-inbound?poCode=${encodeURIComponent(poCode)}&rows=20&page=1&sidx=GRNdate&sord=desc`).then((result) => setRows(result.inboundList || [])).catch((error) => onNotice({ msg: error.message, type: 'err' }));
  }, [poCode, onNotice]);
  return <section id="poInboundTab" aria-label="PO Inbound" className="p-4"><fieldset id="poInboundTabFieldset" className="border border-slate-300 p-3"><div className="grid max-w-md grid-cols-[130px_1fr] items-center gap-2"><span id="poMainForm_poMain_poCode" className="text-right text-xs font-medium text-slate-600">PO Code</span><strong id="poCode_inbound" className="text-xs font-normal text-slate-700">{poCode || ''}</strong></div></fieldset><table id="inboundList" className="mt-2 w-full border-collapse"><thead><tr>{['Inbound No','Inbound Date','GRN No','ASN No','GRN Date','Invoice No','Status'].map((heading)=><Th key={heading}>{heading}</Th>)}</tr></thead><tbody>{rows.map((row)=><tr key={`${row.inboundNo}-${row.GRNNo}`}><Td><button type="button" onClick={()=>navigate(`/app/grn?inboundNumber=${encodeURIComponent(row.inboundNo)}&receiveType=${encodeURIComponent(row.commonInboundType||'PO')}`)} className="font-semibold text-sky-700">{row.inboundNo}</button><div className="mt-1 text-[10px]">ExpQty {row.expQty} &nbsp; RcvdQty {row.rcvQty}</div></Td><Td>{row.createDate}</Td><Td>{row.GRNNo}</Td><Td>{row.asnNumber}</Td><Td>{row.GRNDate}</Td><Td>{row.invoiceNo}</Td><Td><Status value={row.status}/></Td></tr>)}</tbody></table></section>;
}
type PoAsnRow = { asnNo: string; asnDate: string; invoiceNo: string; transporter: string; status: string; closedQty: number|string; asnQty: number|string; asnRcvdQty: number|string };
function PoAsnPanel({ poCode, onNotice }: { poCode?: string; onNotice: (notice: Notice) => void }) {
  const navigate = useNavigate(); const [rows, setRows] = useState<PoAsnRow[]>([]); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(20); const [records, setRecords] = useState(0);
  useEffect(() => {
    if (!poCode) return;
    apiGet<any>(`/api/purchase-order-asn?poCode=${encodeURIComponent(poCode)}&rows=${pageSize}&page=${page}&sidx=&sord=asc`).then((result) => { setRows(result.asnEnquiryDTOList || []); setRecords(Number(result.records) || 0); }).catch((error) => onNotice({ msg: error.message, type: 'err' }));
  }, [poCode, page, pageSize, onNotice]);
  const total = Math.ceil(records / pageSize);
  return <section id="poASNTab" aria-label="ASN" className="p-4"><table id="ASNList" className="w-full border-collapse"><thead><tr>{['ASN No.','ASN date','InvoiceNo','Transporter','Status'].map((heading)=><Th key={heading}>{heading}</Th>)}</tr></thead><tbody>{rows.length ? rows.map((row)=><tr key={row.asnNo}><Td><button type="button" onClick={()=>navigate(`/app/grn?asnNo=${encodeURIComponent(row.asnNo)}`)} className="font-semibold text-sky-700">{row.asnNo}</button><div className="mt-1 grid grid-cols-2 gap-x-3 text-[10px]"><span>Closed <b>{row.closedQty}</b></span><span>Exp Qty <b>{row.asnQty}</b></span><span>Rcv Qty <b>{row.asnRcvdQty}</b></span></div></Td><Td>{row.asnDate}</Td><Td>{row.invoiceNo}</Td><Td>{row.transporter}</Td><Td><Status value={row.status}/></Td></tr>) : <tr><td colSpan={5} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr>}</tbody></table><div className="mt-2 flex items-center justify-end gap-2 text-xs"><span>Page</span><input aria-label="ASN page" className="w-10 border px-1 text-center" type="number" min="1" max={Math.max(1,total)} value={total ? page : 0} onChange={(event)=>{const next=Number(event.target.value);if(next>=1&&next<=total)setPage(next)}}/><span>of {total}</span><select aria-label="ASN page size" value={pageSize} onChange={(event)=>{setPageSize(Number(event.target.value));setPage(1)}} className="border px-1"><option>20</option><option>50</option><option>100</option><option>200</option></select><span>{records ? `View ${(page-1)*pageSize+1} - ${Math.min(page*pageSize,records)} of ${records}` : 'No records to view'}</span></div></section>;
}
function PoImportPanel({ onNotice }: { onNotice: (notice: Notice) => void }) {
  const [file, setFile] = useState<File | null>(null);
  const reset = () => setFile(null);
  const submit = () => {
    if (!file) { onNotice({ msg: 'No file chosen to import.', type: 'err' }); return; }
    onNotice({ msg: 'PO Import upload is not enabled locally because the live multipart response has not been safely observed.', type: 'err' });
  };
  return <section id="poImportTab" aria-label="Import" className="p-4">
    <p className="mb-3 text-xs text-amber-700">PO Import is paused until a validated parser and persistent import workflow are connected. Admin &gt; Common Import &gt; PO Import is also unavailable in this checkout.</p>
    <div className="flex flex-wrap items-center gap-3 text-xs text-slate-600"><label>Import Batch No <input aria-label="Import Batch No" className="ci ml-2 w-40" readOnly value="" /></label><span id="fileName" aria-disabled="true" title="A verified template is not available while PO Import is paused" className="cursor-not-allowed text-slate-400">Download Template unavailable</span><label>Upload Template <input id="importFile" name="importFile" type="file" className="ml-2" disabled aria-label="Upload Template unavailable while import is paused" /></label><button id="importButton" type="button" disabled title="PO Import is paused until its parser and persistence workflow are verified" onClick={submit} className="border px-3 py-1 disabled:cursor-not-allowed disabled:opacity-50">Import</button><button id="resetButton" type="button" onClick={reset} className="border px-3 py-1">Reset</button></div>
    <p className="mt-3 text-xs font-semibold">**Note: Max 2000 rows can be imported in an attempt of Import</p>
    <table id="poimportList" className="mt-3 w-full"><thead><tr>{['Seq No','PO Code','Import File Name','SKU','Remarks'].map((heading)=><Th key={heading}>{heading}</Th>)}</tr></thead><tbody><tr><td colSpan={5} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr></tbody></table><div className="mt-2 text-right text-xs">Page of 0</div>
  </section>;
}
function ObservedPanel({ title }: { title: string }) {
  const [rows, setRows] = useState<number[]>([0]);
  if (title === 'Attached Document') return <section id="poDocumentTab" aria-label="Attached Document" className="p-4"><table id="table" className="w-full"><tbody>{rows.map((row, index)=><tr key={row}><td><input id={index===0?'fileLst':undefined} name="fileLst" type="file" className="poFileList" aria-label={`Document file ${index+1}`}/></td><td className="w-28"><button id={index===0?'_scanSku':undefined} type="button" onClick={()=>setRows([...rows,Math.max(...rows)+1])} className="border px-3 py-1 text-xs">Add New Row</button></td><td className="w-24"><button id={index===0?'removeSkuBtn':undefined} type="button" onClick={()=>setRows(rows.length===1?[rows[0]]:rows.filter((value)=>value!==row))} className="border px-3 py-1 text-xs">Delete Row</button></td></tr>)}</tbody></table><table id="uploadedDocTable" className="mt-3 w-full"><tbody><tr><td><label id="poMainForm_vendormaintenance_lbl_documenaAttached" className="text-xs text-slate-600">Document Attached</label></td></tr></tbody></table></section>;
  return <section aria-label={title} className="p-5 text-sm text-slate-600"><h3 className="font-semibold text-slate-800">{title}</h3></section>;
}
const Grid=({headings}:{headings:string[]})=><table className="mt-3 w-full"><thead><tr>{headings.map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody><tr><td colSpan={headings.length} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr></tbody></table>;
const Pagination=()=> <div className="mt-2 text-right text-xs">Page of 0 <select className="ml-2"><option>20</option><option>50</option><option>100</option><option>200</option></select></div>;
const TopActions = ({ onSearch, onReset, onAdd, onExport, addLabel = 'Add New' }: { onSearch: () => void; onReset: () => void; onAdd: () => void; onExport?: () => void; addLabel?: string }) => <div className="mb-2 flex justify-end gap-2"><Btn variant="warn" onClick={onSearch}><Search size={13}/> Search</Btn><Btn variant="ghost" onClick={onReset}><RotateCcw size={13}/> Reset</Btn>{onExport && <Btn variant="ghost" onClick={onExport}><Download size={13}/> Export</Btn>}<Btn variant="ghost" onClick={onAdd}><Plus size={13}/> {addLabel}</Btn></div>;

export function CategoryBuyers() {
  const [rows, setRows] = useState<any[]>([]); const [show, setShow] = useState(false); const [advanced, setAdvanced] = useState(false);
  const [tab, setTab] = useState<'details'|'udf'>('details'); const [notice, setNotice] = useState<Notice>(null);
  const blank = { buyer_name: '', description: '', email: '', phone: '', alternate_phone: '', active: true, categories: [] as string[], udf: ['', '', '', '', ''] };
  const [form, setForm] = useState(blank); const [filters, setFilters] = useState({ code: '', name: '', description: '', phone: '', email: '', status: '', alternate: '', category: '' });
  const load = () => apiGet<any[]>('/api/procurement?entity=buyers').then(setRows).catch((e) => setNotice({ msg: e.message, type: 'err' }));
  useEffect(() => { void load(); }, []);
  const filtered = useMemo(() => rows.filter((r) => {
    const has = (v: unknown, q: string) => !q || String(v || '').toLowerCase().includes(q.toLowerCase());
    return has(r.buyer_code, filters.code) && has(r.buyer_name, filters.name) && has(r.description, filters.description) && has(r.phone, filters.phone) && has(r.email, filters.email)
      && (!filters.status || (r.active ? 'Active' : 'Inactive') === filters.status) && has(r.alternate_phone, filters.alternate) && has((r.categories || []).join(' '), filters.category);
  }), [rows, filters]);
  const save = async () => { try { await apiSend('/api/procurement?entity=buyers', 'POST', { entity: 'buyers', ...form }); setShow(false); setForm(blank); setNotice({ msg: 'Category Buyer saved successfully.', type: 'ok' }); load(); } catch (e: any) { setNotice({ msg: e.message, type: 'err' }); } };
  const reset = () => setFilters({ code: '', name: '', description: '', phone: '', email: '', status: '', alternate: '', category: '' });
  return <Shell active="procurement" breadcrumb="Procurement > Buyers" openScreens={[{label:'Category Buyers',to:'#'}]}>
    <TopActions onSearch={() => {}} onReset={reset} onAdd={() => { setTab('details'); setShow(true); }} />
    <div className="overflow-hidden border border-slate-300 bg-white"><table className="w-full border-collapse"><thead><tr>{['Buyer Code','Buyer Name','Buyer Description','Phone','Email','Status','Location','Created By','Actions'].map(x=><Th key={x}>{x}</Th>)}</tr><tr>{['code','name','description','phone','email'].map(k=><th key={k} className="border-r border-t border-slate-200 bg-white p-1"><input aria-label={`Filter ${k}`} value={(filters as any)[k]} onChange={e=>setFilters({...filters,[k]:e.target.value})} className="w-full border border-slate-300 px-1 py-1 text-xs"/></th>)}<th className="border-t p-1"><select aria-label="Filter status" className="w-full border p-1 text-xs" value={filters.status} onChange={e=>setFilters({...filters,status:e.target.value})}><option value="">All</option><option>Active</option><option>Inactive</option></select></th><th/><th/><th/></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><Td><button className="text-sky-600">{r.buyer_code}</button></Td><Td>{r.buyer_name}</Td><Td>{r.description}</Td><Td>{r.phone}</Td><Td>{r.email}</Td><Td><Status value={r.active?'Active':'Inactive'}/></Td><Td>{r.location}</Td><Td>{r.created_by}</Td><Td><button onClick={()=>{setForm({...blank,...r});setShow(true)}} className="text-amber-500">✎</button></Td></tr>)}</tbody></table><div className="border-t px-3 py-2 text-right text-[11px] text-slate-500">View 1 - {filtered.length} of {filtered.length}</div></div>
    <button onClick={()=>setAdvanced(!advanced)} className="mt-2 text-xs text-sky-600">{advanced?'Hide':'Advanced Search'}</button>{advanced&&<div className="mt-2 grid grid-cols-2 gap-2 bg-white p-3"><input className="ci" placeholder="Alternate Phone" value={filters.alternate} onChange={e=>setFilters({...filters,alternate:e.target.value})}/><input className="ci" placeholder="Category" value={filters.category} onChange={e=>setFilters({...filters,category:e.target.value})}/></div>}
    <Modal title="Category Buyer Create/Edit" open={show} onClose={()=>setShow(false)} wide><div className="border-b"><Tab active={tab==='details'} onClick={()=>setTab('details')}>Create/Edit</Tab><Tab active={tab==='udf'} onClick={()=>setTab('udf')}>User Defined Fields</Tab></div>{tab==='details'?<div className="mx-auto grid max-w-xl gap-2 py-4"><Field label="Buyer Code"><input className="ci bg-slate-100" disabled value={(form as any).buyer_code||''}/></Field><Field label="Buyer Name" required><input className="ci" value={form.buyer_name} onChange={e=>setForm({...form,buyer_name:e.target.value})}/></Field><Field label="Buyer Description"><input className="ci" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Email" required><input className="ci" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field><Field label="Phone" required><input className="ci" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></Field><Field label="Alternate PhNo"><input className="ci" value={form.alternate_phone} onChange={e=>setForm({...form,alternate_phone:e.target.value})}/></Field><Field label="Is Active"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/></Field><Field label="Category"><select multiple className="ci h-20" value={form.categories} onChange={e=>setForm({...form,categories:Array.from(e.target.selectedOptions,o=>o.value)})}>{['Apparel','Books','Electronics','Healthcare','media'].map(x=><option key={x}>{x}</option>)}</select></Field></div>:<div className="mx-auto grid max-w-xl gap-2 py-4">{form.udf.map((v,i)=><Field key={i} label={`UDF ${i+1}`}><input className="ci" value={v} onChange={e=>{const udf=[...form.udf];udf[i]=e.target.value;setForm({...form,udf})}}/></Field>)}</div>}<div className="flex justify-end gap-2"><Btn onClick={save}>Save</Btn><Btn variant="ghost" onClick={()=>setShow(false)}>Close</Btn></div></Modal>
    {notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
}

const PO_TABS = ['Purchase Order','Additional Charges','User Defined Fields','Terms and Conditions','Comment History','PO Tags','PO Inbound','ASN','Import','Attached Document'];
const LOCATIONS = [{code:'22',name:'Franchise',type:'Franchise'},{code:'APW',name:'Amazon Warehouse',type:'WH'},{code:'ASW',name:'Warehouse-Nation',type:'WH'},{code:'AWL',name:'ATL Warehouse',type:'Store'},{code:'AHH',name:'West Coast Warehouse',type:'WH'}];

export function PurchaseOrderEditor({ mode = 'Multiple Location' }: { mode?: 'Single Location'|'Multiple Location' }) {
  const [vendors,setVendors]=useState<any[]>([]); const [skus,setSkus]=useState<any[]>([]); const [activeTab,setActiveTab]=useState('Purchase Order');
  const [vendorPicker,setVendorPicker]=useState(false); const [customerPicker,setCustomerPicker]=useState(false); const [mailOpen,setMailOpen]=useState(false); const [allocPicker,setAllocPicker]=useState(false); const [allocStep,setAllocStep]=useState(1); const [skuPicker,setSkuPicker]=useState(false);
  const [selectedLocs,setSelectedLocs]=useState<string[]>([]); const [selectedSkus,setSelectedSkus]=useState<string[]>([]); const [record,setRecord]=useState<any>(null); const [notice,setNotice]=useState<Notice>(null);
  const [form,setForm]=useState({vendor_code:'',vendor:'',po_type:'Outright',po_method:mode==='Multiple Location'?'Cross dock':'Single Location',buyer_name:'',warehouse:'',recv_validation_code:'',external_po_no:'',reference_no:'',notes:'',customer_code:'',form_c:false,discount_type:'',discount_value:'',manual_exp_delivery:false,currency_code:'',auto_email:false,expected_date:new Date().toISOString().slice(0,10),allocation_method:'Even Distribution',udf:['','','','','','','','','',''],terms:'',comment:'',tags:[] as string[],additional_charges:[] as AdditionalCharge[]});
  useEffect(()=>{
    apiGet<any[]>('/api/vendors').then(setVendors);apiGet<any[]>('/api/skus').then(setSkus);
    const poId = new URLSearchParams(window.location.search).get('poId');
    if (poId) apiGet<any>(`/api/purchase-orders?id=${encodeURIComponent(poId)}`).then((po) => {
      setRecord(po);
      setSelectedSkus((po.line_items || []).map((line: any) => line.sku_code));
      setSelectedLocs(po.delivery_locations || []);
      setForm((current) => ({ ...current, ...po, additional_charges: po.additional_charges || [] }));
    }).catch((error) => setNotice({ msg: error.message, type: 'err' }));
  },[]);
  const lines=skus.filter(s=>selectedSkus.includes(s.sku_code)).map(s=>({sku_code:s.sku_code,description:s.name,po_qty:1,mrp:s.mrp,unit_cost:s.cost_price,unit_base_cost:s.cost_price,delivery_date:form.expected_date,tax:'GST',additional_charge:0}));
  const total=lines.reduce((n,l)=>n+l.unit_cost*l.po_qty,0);
  const save = async () => { try { const payload={po_no:record?.po_no||'PO'+Date.now().toString().slice(-8),vendor:form.vendor,vendor_code:form.vendor_code,warehouse:form.warehouse,po_date:record?.po_date||new Date().toISOString().slice(0,10),expected_date:form.expected_date,items:lines.length,qty:lines.reduce((n,l)=>n+l.po_qty,0),amount:total,buyer_name:form.buyer_name,po_type:form.po_type,recv_validation_code:form.recv_validation_code,external_po_no:form.external_po_no,reference_no:form.reference_no,notes:form.notes,po_method:form.po_method,delivery_locations:selectedLocs.length?selectedLocs:[form.warehouse],line_items:lines,allocation:selectedLocs.map(code=>({code,method:form.allocation_method,ratio:1})),udf:form.udf,terms:form.terms,additional_charges:form.additional_charges}; const created=record ? await apiSend('/api/purchase-orders','PUT',{id:record.id,...payload}) : await apiSend('/api/purchase-orders','POST',{...payload,status:'Pending Confirmation'}); setRecord(created);setForm((current)=>({...current,additional_charges:created.additional_charges||[]}));setNotice({msg:'PO saved successfully.',type:'ok'});return created;} catch(e:any){setNotice({msg:e.message,type:'err'});return null;} };
  const saveUdf = async () => {
    if (!record) return;
    const udf = Array.from({ length: 10 }, (_, index) => String(form.udf[index] || '').trim());
    if (!udf.some(Boolean)) return setNotice({ msg: 'No Data In UDF Fields to Save', type: 'err' });
    try {
      const updated = await apiSend<any>('/api/purchase-orders', 'PUT', { id: record.id, udf });
      setRecord(updated); setForm({ ...form, udf: updated.udf });
      setNotice({ msg: 'UDF fields Updated successfully', type: 'ok' });
    } catch (error: any) { setNotice({ msg: error.message, type: 'err' }); }
  };
  const addComment = async () => {
    if (!record) return;
    if (form.comment === '') return setNotice({ msg: 'Please Enter Some Comments', type: 'err' });
    try {
      const result = await apiSend<any>('/api/purchase-order-comments', 'POST', { po_id: record.id, commentDet: form.comment });
      const entry = result.poDTO;
      const comments = [{ comment_date: entry.commentDate, comment_added_by: entry.commentAddedBy, comment_status: entry.commentStatus, view_comments: entry.viewComments }, ...(record.comments || [])];
      setRecord({ ...record, comments }); setForm({ ...form, comment: '' });
    } catch (error: any) { setNotice({ msg: error.message, type: 'err' }); }
  };
  const confirm=async()=>{const row=await save();if(!row)return;try{const updated=await apiSend('/api/purchase-orders','PUT',{id:row.id,action:'confirm'});setRecord(updated);setNotice({msg:'PO confirmed successfully.',type:'ok'})}catch(e:any){setNotice({msg:e.message,type:'err'})}};
  const release=async()=>{if(!record)return setNotice({msg:'Save and confirm the Purchase Order before release.',type:'err'});try{const updated=await apiSend('/api/purchase-orders','PUT',{id:record.id,action:'release'});setRecord(updated);setNotice({msg:'PO released successfully.',type:'ok'})}catch(e:any){setNotice({msg:e.message,type:'err'})}};
  const toggleSku=(code:string)=>setSelectedSkus(s=>s.includes(code)?s.filter(x=>x!==code):[...s,code]);
  return <Shell active="procurement" breadcrumb={`Procurement > PO Create/Edit > ${mode}`} openScreens={[{label:mode==='Multiple Location'?'Multiple Location':'Single Location',to:'#'}]}><div className="border border-slate-300 bg-white">
    <div className="flex flex-wrap justify-end gap-2 border-b p-2"><Btn variant="warn" onClick={save}>Save</Btn><Btn onClick={release}>Release</Btn><Btn variant="ghost" onClick={()=>setMailOpen(true)}>Send Mail</Btn><Btn variant="ghost" onClick={()=>setMailOpen(true)}>ReSend Mail</Btn>{record?.status!=='Confirmed'&&<Btn onClick={confirm}><Check size={13}/> Confirm</Btn>}<Btn variant="ghost" onClick={()=>{setRecord(null);setSelectedSkus([])}}>Add New</Btn><Btn variant="ghost" onClick={()=>window.history.back()}>Back to Enqiry</Btn><Btn variant="ghost" onClick={()=>setNotice({msg:'Additional overflow actions are live-observed but their workflow is not yet verified locally.',type:'err'})}>Toggle Dropdown</Btn></div>
    <div className="border-b">{PO_TABS.map(t=><Tab key={t} active={activeTab===t} onClick={()=>setActiveTab(t)}>{t}</Tab>)}</div>
    {activeTab==='Purchase Order'&&<><div className="grid grid-cols-3 gap-x-8 gap-y-2 p-4"><Field label="Vendor Code" required><button onClick={()=>setVendorPicker(true)} className="ci text-left">{form.vendor_code||'Select...'}</button></Field><Field label="Delivery Location"><select className="ci" value={form.warehouse} onChange={e=>setForm({...form,warehouse:e.target.value})}><option value="">--- Select ---</option>{LOCATIONS.map(x=><option key={x.code}>{x.name}</option>)}</select></Field><Field label="PO Type"><select className="ci" value={form.po_type} onChange={e=>setForm({...form,po_type:e.target.value})}>{['Outright','ARS','CIF','Consignment','FNV','Blanket','SOR','Outright-Direct Inbound','Aggregate'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Buyer Code" required><input className="ci" value={form.buyer_name} onChange={e=>setForm({...form,buyer_name:e.target.value})}/></Field><Field label="Recv Valid. Code" required><select className="ci" value={form.recv_validation_code} onChange={e=>setForm({...form,recv_validation_code:e.target.value})}><option value="">--- Select ---</option><option>No Excess Receiving</option></select></Field><Field label="Form C"><input type="checkbox" checked={form.form_c} onChange={e=>setForm({...form,form_c:e.target.checked})}/></Field><Field label="External PO No"><input className="ci" value={form.external_po_no} onChange={e=>setForm({...form,external_po_no:e.target.value})}/></Field><Field label="Reference No"><input className="ci" value={form.reference_no} onChange={e=>setForm({...form,reference_no:e.target.value})}/></Field><Field label="Notes"><textarea className="ci" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field><Field label="Customer Code"><button onClick={()=>setCustomerPicker(true)} className="ci text-left">{form.customer_code||'Select...'}</button></Field><Field label="Discount Type"><select className="ci" value={form.discount_type} onChange={e=>setForm({...form,discount_type:e.target.value})}><option value="">--- Select ---</option><option>Percentage</option><option>Absolute</option></select></Field><Field label="Discount Value"><input className="ci" value={form.discount_value} onChange={e=>setForm({...form,discount_value:e.target.value})}/></Field><Field label="Manual ExpDel Date"><input type="checkbox" checked={form.manual_exp_delivery} onChange={e=>setForm({...form,manual_exp_delivery:e.target.checked})}/></Field><Field label="Exp. Delivery Date"><input className="ci" type="date" value={form.expected_date} onChange={e=>setForm({...form,expected_date:e.target.value})}/></Field><Field label="Currency Code"><select className="ci" value={form.currency_code} onChange={e=>setForm({...form,currency_code:e.target.value})}><option value="">--- Select ---</option>{['AED','BHD','CAD','CHF','CNY','EGP','EUR','GBP','HKD','IDR','INR','JPY','USD'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Auto Email"><input type="checkbox" checked={form.auto_email} onChange={e=>setForm({...form,auto_email:e.target.checked})}/></Field><Field label="Status"><Status value={record?.status||'Pending Confirmation'}/></Field></div><div className="flex flex-wrap gap-1 border-t px-3 py-2"><button onClick={()=>{setAllocStep(1);setAllocPicker(true)}} className="bg-emerald-500 px-3 py-1 text-xs text-white">Manage Allocation</button><button onClick={()=>setSkuPicker(true)} disabled={mode==='Multiple Location'&&!selectedLocs.length} className="bg-amber-500 px-3 py-1 text-xs text-white disabled:opacity-40">Add SKU</button><button onClick={()=>setSelectedSkus([])} className="bg-indigo-500 px-3 py-1 text-xs text-white">Remove SKU</button>{['Update Cost','Import','Clear Discount','Import Failed SKU List'].map(x=><button key={x} onClick={()=>setNotice({msg:`${x} workflow is live-observed but not yet verified locally.`,type:'err'})} className="border px-3 py-1 text-xs">{x}</button>)}</div><table className="w-full"><thead><tr>{['SKU Code','PO Qty','MRP','Unit Cost','Qty','Attributes','Delivery Date','Discount','Discount2','Tax','Charges/Amount','% For SO','UDF'].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody>{lines.map(l=><tr key={l.sku_code}><Td>{l.sku_code}<div className="text-[10px]">{l.description}</div></Td><Td>{l.po_qty.toFixed(2)}</Td><Td>{l.mrp.toFixed(2)}</Td><Td>{l.unit_cost.toFixed(2)}</Td><Td>{l.po_qty.toFixed(2)}</Td><Td>Default</Td><Td>{l.delivery_date}</Td><Td>0</Td><Td>0</Td><Td>Tax Group</Td><Td>0.00</Td><Td>0</Td><Td>—</Td></tr>)}</tbody></table>{record&&<aside className="absolute right-6 top-52 w-52 border-l bg-white p-3 text-[11px] shadow"><b>PO Details</b><p>PO Code: {record.po_no}</p><p>PO Date: {record.po_date}</p><p>Total PO Qty: {record.qty}</p><p>PO Amount: {record.amount}</p><p>Status: {record.status}</p></aside>}</>}
    {activeTab==='Additional Charges'&&<AdditionalChargesPanel charges={form.additional_charges} onChange={(additional_charges)=>setForm({...form,additional_charges})}/>} {activeTab==='User Defined Fields'&&<PurchaseOrderUdfPanel values={form.udf} saved={Boolean(record)} onChange={(udf)=>setForm({...form,udf})} onSave={saveUdf}/>} {activeTab==='Terms and Conditions'&&<TermsAndConditionsPanel value={form.terms} onChange={(terms)=>setForm({...form,terms})} onSave={()=>{void save()}}/>}{activeTab==='Comment History'&&<CommentHistoryPanel value={form.comment} comments={record?.comments||[]} saved={Boolean(record)} onChange={(comment)=>setForm({...form,comment})} onSubmit={()=>{void addComment()}}/>}{activeTab==='PO Tags'&&<PoTagsPanel poCode={record?.po_no} status={record?.status||'Pending Confirmation'} onNotice={setNotice} onPersist={(tags)=>setRecord({...record,tags})}/>} {activeTab==='PO Inbound'&&<PoInboundPanel poCode={record?.po_no} onNotice={setNotice}/>} {activeTab==='ASN'&&<PoAsnPanel poCode={record?.po_no} onNotice={setNotice}/>} {activeTab==='Import'&&<PoImportPanel onNotice={setNotice}/>} {activeTab==='Attached Document'&&<ObservedPanel title="Attached Document"/>}
  </div>
  <Modal title="Select Vendor" open={vendorPicker} onClose={()=>setVendorPicker(false)} wide><table className="w-full"><thead><tr><Th>Vendor Code</Th><Th>Vendor Name</Th><Th>Vendor Address</Th></tr></thead><tbody>{vendors.map(v=><tr key={v.id} onDoubleClick={()=>{setForm({...form,vendor_code:v.vendor_code,vendor:v.vendor_name});setVendorPicker(false)}} className="cursor-pointer hover:bg-sky-50"><Td>{v.vendor_code}</Td><Td>{v.vendor_name}</Td><Td>{[v.city,v.state,v.country].filter(Boolean).join(', ')}</Td></tr>)}</tbody></table><div className="mt-3 flex justify-end"><Btn variant="ghost" onClick={()=>setVendorPicker(false)}>Close</Btn></div></Modal><Modal title="Select Customer" open={customerPicker} onClose={()=>setCustomerPicker(false)}><p className="text-sm text-slate-600">Customer lookup is structurally present from the live screen; its result workflow is not yet observed.</p><div className="mt-3 text-right"><Btn variant="ghost" onClick={()=>setCustomerPicker(false)}>Close</Btn></div></Modal><Modal title="Send Mail" open={mailOpen} onClose={()=>setMailOpen(false)}><Field label="To"><input className="ci"/></Field><Field label="CC"><input className="ci"/></Field><div className="mt-4 flex justify-end gap-2"><Btn onClick={()=>{setMailOpen(false);setNotice({msg:'Live mail delivery has not been verified locally.',type:'err'})}}>OK</Btn><Btn variant="ghost" onClick={()=>setMailOpen(false)}>Close</Btn></div></Modal>
  <Modal title="Manage Allocation" open={allocPicker} onClose={()=>setAllocPicker(false)} wide>{allocStep===1?<><div className="grid grid-cols-[1fr_80px_1fr] gap-3"><table><thead><tr><Th>Loc Code</Th><Th>Loc Name</Th><Th>Type</Th></tr></thead><tbody>{LOCATIONS.map(l=><tr key={l.code}><Td><label><input type="checkbox" checked={selectedLocs.includes(l.code)} onChange={()=>setSelectedLocs(s=>s.includes(l.code)?s.filter(x=>x!==l.code):[...s,l.code])}/> {l.code}</label></Td><Td>{l.name}</Td><Td>{l.type}</Td></tr>)}</tbody></table><div className="flex flex-col justify-center gap-2"><button className="bg-emerald-500 py-1 text-xs text-white">Add</button><button className="bg-amber-500 py-1 text-xs text-white">Remove</button></div><table><thead><tr><Th>Loc Code</Th><Th>Loc Name</Th><Th>Type</Th></tr></thead><tbody>{LOCATIONS.filter(l=>selectedLocs.includes(l.code)).map(l=><tr key={l.code}><Td>{l.code}</Td><Td>{l.name}</Td><Td>{l.type}</Td></tr>)}</tbody></table></div><div className="mt-3 flex justify-end gap-2"><Btn variant="warn" onClick={()=>setAllocStep(2)}>Next</Btn><Btn variant="ghost" onClick={()=>setAllocPicker(false)}>Cancel</Btn></div></>:<><table className="w-full"><thead><tr><Th>Loc Code</Th><Th>Loc Name</Th><Th>Type</Th><Th>Alloc Method</Th></tr></thead><tbody>{LOCATIONS.filter(l=>selectedLocs.includes(l.code)).map(l=><tr key={l.code}><Td>{l.code}</Td><Td>{l.name}</Td><Td>{l.type}</Td><Td><select className="ci" value={form.allocation_method} onChange={e=>setForm({...form,allocation_method:e.target.value})}><option>Even Distribution</option><option>Custom Ratio</option></select></Td></tr>)}</tbody></table><div className="mt-3 flex justify-end gap-2"><Btn variant="warn" onClick={()=>setAllocStep(1)}>Back</Btn><Btn variant="warn" onClick={()=>setAllocPicker(false)}>Save</Btn><Btn variant="ghost" onClick={()=>setAllocPicker(false)}>Cancel</Btn></div></>}</Modal>
  <Modal title="ADD SKU(s)" open={skuPicker} onClose={()=>setSkuPicker(false)} wide><table className="w-full"><thead><tr><Th></Th><Th>SKU Code</Th><Th>SKU Description</Th><Th>Style</Th><Th>UOM</Th><Th>PUF</Th><Th>Quantity</Th></tr></thead><tbody>{skus.map(s=><tr key={s.id}><Td><input type="checkbox" checked={selectedSkus.includes(s.sku_code)} onChange={()=>toggleSku(s.sku_code)}/></Td><Td>{s.sku_code}</Td><Td>{s.name}</Td><Td>{s.brand}</Td><Td>{s.uom}</Td><Td>1</Td><Td>1</Td></tr>)}</tbody></table><div className="mt-3 flex justify-end gap-2"><Btn onClick={()=>setSkuPicker(false)}>Add SKU</Btn><Btn variant="ghost" onClick={()=>setSkuPicker(false)}>Close</Btn></div></Modal>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
}

function LegacyPOEnquiry() {
  const nav=useNavigate();const [rows,setRows]=useState<any[]>([]);const [filters,setFilters]=useState({po:'',date:'',vendor:'',type:'',status:'',location:''});
  const load=()=>apiGet<any[]>('/api/purchase-orders').then(setRows);useEffect(()=>{void load()},[]);const filtered=rows.filter(r=>(!filters.po||r.po_no?.includes(filters.po))&&(!filters.date||r.po_date===filters.date)&&(!filters.vendor||String(r.vendor).toLowerCase().includes(filters.vendor.toLowerCase()))&&(!filters.type||r.po_type===filters.type)&&(!filters.status||r.status===filters.status)&&(!filters.location||r.warehouse===filters.location));
  const reset=()=>setFilters({po:'',date:'',vendor:'',type:'',status:'',location:''});return <Shell active="procurement" breadcrumb="Procurement > PO Enquiry" openScreens={[{label:'PO Enquiry',to:'#'}]}><TopActions onSearch={()=>{}} onReset={reset} onAdd={()=>nav('/app/procurement/po/single')} addLabel="Add New"/><div className="grid grid-cols-6 gap-2 border bg-white p-3"><input className="ci" placeholder="PO Code" value={filters.po} onChange={e=>setFilters({...filters,po:e.target.value})}/><input className="ci" type="date" value={filters.date} onChange={e=>setFilters({...filters,date:e.target.value})}/><input className="ci" placeholder="Vendor" value={filters.vendor} onChange={e=>setFilters({...filters,vendor:e.target.value})}/><select className="ci" value={filters.type} onChange={e=>setFilters({...filters,type:e.target.value})}><option value="">PO Type</option><option>Outright/Direct Inbound</option><option>Consignment</option></select><select className="ci" value={filters.status} onChange={e=>setFilters({...filters,status:e.target.value})}><option value="">Status</option>{['Pending Confirmation','Confirmed','Released','ReOpen','ReConfirmed','Partially Received','Received','Closed','Cancelled'].map(x=><option key={x}>{x}</option>)}</select><input className="ci" placeholder="Delivery Location" value={filters.location} onChange={e=>setFilters({...filters,location:e.target.value})}/></div><table className="mt-2 w-full bg-white"><thead><tr>{['PO Code','PO Date','Vendor Code','PO Type','PO Amount','Delivery Location','PO Release Date','Status'].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody>{filtered.map(r=><tr key={r.id}><Td>{r.po_no}</Td><Td>{r.po_date}</Td><Td>{r.vendor_code||r.vendor}</Td><Td>{r.po_type}</Td><Td>{r.amount}</Td><Td>{r.warehouse}</Td><Td>{r.release_date||'—'}</Td><Td><Status value={r.status}/></Td></tr>)}</tbody></table></Shell>;
}

export function POEnquiry() {
  const nav = useNavigate();
  const initial = { poCode: '', extPoNo: '', poDate: '', expiryDate: '', vendor: '', poType: '', status: '', deliveryLocation: '', masterPoCode: '' };
  const advancedInitial = { skuCode: '', vendorRefNo: '', buyer: '', poReleaseDate: '', poMode: '', pending: '', sourceLocation: '', brand: '', poTag: '', multiLocation: '', poMethod: '', skuOrBarcode: '' };
  const [rows, setRows] = useState<any[]>([]);
  const [filters, setFilters] = useState(initial);
  const [advancedFilters, setAdvancedFilters] = useState(advancedInitial);
  const [applied, setApplied] = useState<typeof initial | null>(null);
  const [advanced, setAdvanced] = useState(false);
  const [gridFilters, setGridFilters] = useState(false);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState<Notice>(null);
  const load = async () => { setLoading(true); try { setRows(await apiGet<any[]>('/api/purchase-orders')); } catch (error: any) { setNotice({ msg: error.message || 'Unable to load purchase orders.', type: 'err' }); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);

  const poTypes = ['CIF', 'Outright-Direct Inbound', 'Outright', 'ARS', 'FNV', 'Consignment', 'Blanket', 'SOR', 'Aggregate'];
  const statuses = ['Cancelled', 'Closed', 'Confirmed', 'Expired', 'Partially Received', 'Pending Confirmation', 'Received', 'ReConfirmed', 'Released', 'ReOpen', 'Short Closed', 'Error In Releasing', 'Release In Process'];
  const locations = Array.from(new Set(rows.map(row => row.warehouse || row.delivery_location).filter(Boolean)));
  const optionValues = (keys: string[]) => Array.from(new Set(rows.map(row => keys.map(key => row[key]).find(Boolean)).filter(Boolean))).map(String).sort();
  const buyers = optionValues(['buyer_name', 'buyer']); const sourceLocations = optionValues(['source_location', 'sourceLocation']);
  const poModes = ['ARS', 'Auto', 'BackOrder', 'BackOrder/new', 'DirectInbound', 'Manual', 'System'];
  const poTags = ['air', 'CCM', 'gty', 'hgjkhl', 'Perishable Goods', 'po', 'PO Tag6', 'po tag7', 'TESTING', 'Fragile Items', 'PO Tag2', 'PO Tag3', 'PO Tag4', 'PO Tag5'];
  const poMethods = ['Cross dock', 'Drop Ship'];
  const textMatch = (value: unknown, query: string) => !query || String(value || '').toLowerCase().includes(query.toLowerCase());
  const dateMatch = (value: unknown, query: string) => !query || String(value || '').slice(0, 10) === query;
  const filtered = !applied ? [] : rows.filter(row =>
    textMatch(row.po_no || row.po_code, applied.poCode)
    && textMatch(row.external_po_no || row.ext_po_no || row.externalPoNo, applied.extPoNo)
    && dateMatch(row.po_date, applied.poDate)
    && dateMatch(row.expiry_date || row.expiryDate, applied.expiryDate)
    && textMatch(`${row.vendor_code || row.vendor || ''} ${row.vendor_name || ''}`, applied.vendor)
    && (!applied.poType || row.po_type === applied.poType)
    && (!applied.status || row.status === applied.status)
    && textMatch(row.warehouse || row.delivery_location, applied.deliveryLocation)
    && textMatch(row.master_po_code || row.masterPoCode, applied.masterPoCode)
    && textMatch(row.sku_code || row.skuCode, advancedFilters.skuCode)
    && textMatch(row.vendor_reference_no || row.vendorRefNo || row.reference_no, advancedFilters.vendorRefNo)
    && textMatch(row.buyer_name || row.buyer, advancedFilters.buyer)
    && dateMatch(row.release_date || row.po_release_date, advancedFilters.poReleaseDate)
    && textMatch(row.po_mode || row.poMode, advancedFilters.poMode)
    && textMatch(row.pending, advancedFilters.pending)
    && textMatch(row.source_location || row.sourceLocation, advancedFilters.sourceLocation)
    && textMatch(row.brand || row.brand_name, advancedFilters.brand)
    && textMatch(row.po_tag || row.poTag, advancedFilters.poTag)
    && textMatch(row.multi_location || row.multiLocPO, advancedFilters.multiLocation)
    && textMatch(row.po_method || row.poMethod, advancedFilters.poMethod)
    && textMatch(`${row.sku_code || row.skuCode || ''} ${row.barcode || ''}`, advancedFilters.skuOrBarcode)
  );
  const change = (key: keyof typeof initial, value: string) => setFilters(current => ({ ...current, [key]: value }));
  const advancedChange = (key: keyof typeof advancedInitial, value: string) => setAdvancedFilters(current => ({ ...current, [key]: value }));
  const search = () => { setApplied(filters); setPage(1); };
  const reset = () => { setFilters(initial); setAdvancedFilters(advancedInitial); setApplied(null); setAdvanced(false); setGridFilters(false); setPage(1); };
  const totalPages = Math.ceil(filtered.length / pageSize);
  const visibleRows = filtered.slice((page - 1) * pageSize, page * pageSize);
  const columns = ['PO Code', 'Ext PO No', 'PO Date', 'Expiry Date', 'Vendor Name', 'Vendor Code', 'Buyer Name', 'PO Type', 'PO Mode', 'Status', 'PO Amount', 'PO Qty', 'Delivery Location', 'PO Release Date', 'Master PO Code'];

  return <Shell active="procurement" breadcrumb="Procurement > PO Enquiry" openScreens={[{ label: 'PO Enquiry', to: '#' }]}>
    <div className="mb-2 flex flex-wrap justify-end gap-2">
      <Btn variant="warn" onClick={search} disabled={loading}>Search</Btn>
      <Btn variant="ghost" onClick={reset}>Reset</Btn>
      <Btn variant="ghost" onClick={() => setAdvanced(value => !value)}>Advance Search</Btn>
      <Btn variant="ghost" onClick={() => window.print()}>Print</Btn>
      <Btn variant="ghost" onClick={() => setGridFilters(value => !value)}>Toggle Dropdown</Btn>
      <Btn onClick={() => nav('/app/procurement/po/single')}>Add New</Btn>
    </div>
    <section aria-label="PO Enquiry filters" className="grid grid-cols-1 gap-3 border bg-white p-3 sm:grid-cols-2 lg:grid-cols-3">
      <label className="text-xs">PO Code<input aria-label="PO Code" className="ci mt-1 w-full" value={filters.poCode} onChange={event => change('poCode', event.target.value)} /></label>
      <label className="text-xs">Ext PO No<input aria-label="Ext PO No" className="ci mt-1 w-full" value={filters.extPoNo} onChange={event => change('extPoNo', event.target.value)} /></label>
      <label className="text-xs">PO Date<input aria-label="PO Date" className="ci mt-1 w-full" type="date" value={filters.poDate} onChange={event => change('poDate', event.target.value)} /></label>
      <label className="text-xs">Expiry Date<input aria-label="Expiry Date" className="ci mt-1 w-full" type="date" value={filters.expiryDate} onChange={event => change('expiryDate', event.target.value)} /></label>
      <label className="text-xs">Vendor<input aria-label="Vendor" className="ci mt-1 w-full" value={filters.vendor} onChange={event => change('vendor', event.target.value)} /></label>
      <label className="text-xs">PO Type<select aria-label="PO Type" className="ci mt-1 w-full" value={filters.poType} onChange={event => change('poType', event.target.value)}><option value="">--- Select ---</option>{poTypes.map(value => <option key={value}>{value}</option>)}</select></label>
      <label className="text-xs">Status<select aria-label="Status" className="ci mt-1 w-full" value={filters.status} onChange={event => change('status', event.target.value)}><option value="">--- Select ---</option>{statuses.map(value => <option key={value}>{value}</option>)}</select></label>
      <label className="text-xs">Delivery Location<select aria-label="Delivery Location" className="ci mt-1 w-full" value={filters.deliveryLocation} onChange={event => change('deliveryLocation', event.target.value)}><option value="">--- Select ---</option>{locations.map(value => <option key={value}>{value}</option>)}</select></label>
      <label className="text-xs">Master PO Code<input aria-label="Master PO Code" className="ci mt-1 w-full" value={filters.masterPoCode} onChange={event => change('masterPoCode', event.target.value)} /></label>
    </section>
    {advanced && <section aria-label="Advanced PO Enquiry filters" className="mt-2 grid grid-cols-1 gap-3 border bg-slate-50 p-3 sm:grid-cols-2 lg:grid-cols-4">
      <label className="text-xs">SKU Code<input className="ci mt-1 w-full" maxLength={50} value={advancedFilters.skuCode} onChange={e=>advancedChange('skuCode',e.target.value)}/></label><label className="text-xs">Vendor Ref No<input className="ci mt-1 w-full" value={advancedFilters.vendorRefNo} onChange={e=>advancedChange('vendorRefNo',e.target.value)}/></label>
      <label className="text-xs">Buyer Name<select className="ci mt-1 w-full" value={advancedFilters.buyer} onChange={e=>advancedChange('buyer',e.target.value)}><option value="">--- Select ---</option>{buyers.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">PO Release Date<input className="ci mt-1 w-full" type="date" value={advancedFilters.poReleaseDate} onChange={e=>advancedChange('poReleaseDate',e.target.value)}/></label>
      <label className="text-xs">PO Mode<select className="ci mt-1 w-full" value={advancedFilters.poMode} onChange={e=>advancedChange('poMode',e.target.value)}><option value="">--- Select ---</option>{poModes.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Pending<select className="ci mt-1 w-full" value={advancedFilters.pending} onChange={e=>advancedChange('pending',e.target.value)}><option value="">--- Select ---</option><option value="true">Yes</option><option value="false">No</option></select></label>
      <label className="text-xs">Source Location<select className="ci mt-1 w-full" value={advancedFilters.sourceLocation} onChange={e=>advancedChange('sourceLocation',e.target.value)}><option value="">--- Select ---</option>{sourceLocations.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Brand<input className="ci mt-1 w-full" value={advancedFilters.brand} onChange={e=>advancedChange('brand',e.target.value)}/></label>
      <label className="text-xs">PO Tag<select multiple className="ci mt-1 h-20 w-full" value={advancedFilters.poTag ? advancedFilters.poTag.split(',') : []} onChange={e=>advancedChange('poTag',Array.from(e.target.selectedOptions,o=>o.value).join(','))}>{poTags.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Multi Location PO<select multiple className="ci mt-1 h-16 w-full" value={advancedFilters.multiLocation ? advancedFilters.multiLocation.split(',') : []} onChange={e=>advancedChange('multiLocation',Array.from(e.target.selectedOptions,o=>o.value).join(','))}><option>Multi Location</option><option>Single Location</option></select></label>
      <label className="text-xs">PO Method<select className="ci mt-1 w-full" value={advancedFilters.poMethod} onChange={e=>advancedChange('poMethod',e.target.value)}><option value="">--- Select ---</option>{poMethods.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">SKU/Barcode<input className="ci mt-1 w-full" value={advancedFilters.skuOrBarcode} onChange={e=>advancedChange('skuOrBarcode',e.target.value)}/></label>
    </section>}
    <div className="mt-2 overflow-auto"><table className="w-full min-w-[1400px] bg-white"><thead><tr>{columns.map(value => <Th key={value}>{value}</Th>)}</tr>{gridFilters && <tr>{columns.map(value=><th key={value} className="border p-1"><input aria-label={`Filter ${value}`} className="w-full border p-1 text-xs" onChange={event=>{ const key=value==='PO Code'?'poCode':value==='Ext PO No'?'extPoNo':value==='Vendor Name'||value==='Vendor Code'?'vendor':value==='PO Type'?'poType':value==='Status'?'status':value==='Delivery Location'?'deliveryLocation':value==='Master PO Code'?'masterPoCode':''; if(key) change(key as keyof typeof initial,event.target.value); }} /></th>)}</tr>}</thead><tbody>{loading?<tr><td colSpan={15} className="p-5 text-center text-xs text-slate-400">Loading…</td></tr>:visibleRows.length ? visibleRows.map(row => <tr key={row.id || row.po_no}><Td>{row.po_no || row.po_code}</Td><Td>{row.external_po_no || row.ext_po_no}</Td><Td>{row.po_date}</Td><Td>{row.expiry_date || row.expiryDate}</Td><Td>{row.vendor_name || row.vendor}</Td><Td>{row.vendor_code}</Td><Td>{row.buyer_name || row.buyer}</Td><Td>{row.po_type}</Td><Td>{row.po_mode || row.poMode}</Td><Td><Status value={row.status} /></Td><Td>{row.amount}</Td><Td>{row.qty}</Td><Td>{row.warehouse || row.delivery_location}</Td><Td>{row.release_date || '—'}</Td><Td>{row.master_po_code || row.masterPoCode}</Td></tr>) : <tr><td colSpan={15} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr>}</tbody></table></div>
    <div className="mt-2 flex items-center justify-end gap-2 text-xs text-slate-500"><span>Page {filtered.length ? page : 0} of {totalPages}</span><select aria-label="Rows per page" value={pageSize} onChange={e=>{setPageSize(Number(e.target.value));setPage(1)}}><option>20</option><option>50</option><option>100</option><option>200</option></select><Btn variant="ghost" disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</Btn><Btn variant="ghost" disabled={!totalPages||page>=totalPages} onClick={()=>setPage(page+1)}>Next</Btn></div>
    {notice && <Toast {...notice} onClose={() => setNotice(null)} />}
  </Shell>;
}

export function VendorInvoices() {
  const [rows,setRows]=useState<any[]>([]);const [editing,setEditing]=useState(false);const [notice,setNotice]=useState<Notice>(null);const [filters,setFilters]=useState({invoice:'',vendor:'',date:'',posting:'',name:'',status:''});
  const blank={vendor_code:'',vendor_name:'',vendor_invoice_no:'',invoice_date:'',posting_date:'',invoice_amount:'',currency:'INR',grn_codes:[] as string[]};const [form,setForm]=useState(blank);const load=()=>apiGet<any[]>('/api/procurement?entity=invoices').then(setRows);useEffect(()=>{void load()},[]);const filtered=rows.filter(r=>Object.entries(filters).every(([k,v])=>!v||String(k==='invoice'?r.document_invoice_no:k==='vendor'?r.vendor_code:k==='date'?r.invoice_date:k==='posting'?r.posting_date:k==='name'?r.vendor_name:r.status).toLowerCase().includes(v.toLowerCase())));
  const save=async()=>{try{const row=await apiSend('/api/procurement?entity=invoices','POST',{entity:'invoices',...form,invoice_amount:Number(form.invoice_amount)});setNotice({msg:'Vendor Invoice saved successfully.',type:'ok'});setForm(blank);setEditing(false);load();return row}catch(e:any){setNotice({msg:e.message,type:'err'})}};
  if(editing)return <Shell active="procurement" breadcrumb="Procurement > Vendor Invoice > Manage Vendor Invoice" openScreens={[{label:'Vendor Invoice Enquiry',to:'#'},{label:'Manage Vendor Invoice',to:'#'}]}><div className="border bg-white"><div className="flex justify-end gap-2 p-2"><Btn variant="warn" onClick={save}>Save</Btn><Btn onClick={async()=>{const r:any=await save();if(r)await apiSend('/api/procurement','PUT',{entity:'invoices',id:r.id,action:'confirm'})}}>Confirm</Btn><Btn variant="ghost" onClick={()=>setEditing(false)}>Discard</Btn><Btn variant="ghost" onClick={()=>setForm(blank)}>Add New</Btn></div><div className="border-b"><Tab active onClick={()=>{}}>Manage Vendor Invoice</Tab><Tab active={false} onClick={()=>{}}>Import</Tab></div><div className="grid grid-cols-3 gap-x-8 gap-y-3 p-5"><Field label="Vendor Code" required><input className="ci" value={form.vendor_code} onChange={e=>setForm({...form,vendor_code:e.target.value})}/></Field><Field label="Vendor Name"><input className="ci" value={form.vendor_name} onChange={e=>setForm({...form,vendor_name:e.target.value})}/></Field><Field label="Doc Invoice No"><input className="ci bg-slate-100" disabled/></Field><Field label="Vendor Invoice No" required><input className="ci" value={form.vendor_invoice_no} onChange={e=>setForm({...form,vendor_invoice_no:e.target.value})}/></Field><Field label="Invoice Date" required><input className="ci" type="date" value={form.invoice_date} onChange={e=>setForm({...form,invoice_date:e.target.value})}/></Field><Field label="Posting Date" required><input className="ci" type="date" value={form.posting_date} onChange={e=>setForm({...form,posting_date:e.target.value})}/></Field><Field label="Invoice Amount" required><input className="ci" type="number" value={form.invoice_amount} onChange={e=>setForm({...form,invoice_amount:e.target.value})}/></Field><Field label="Currency"><select className="ci" value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}><option>INR</option><option>USD</option></select></Field><Field label="Status"><Status value="Pending"/></Field></div><div className="px-3"><button className="bg-sky-600 px-3 py-1 text-xs text-white">Add GRN</button> <button className="bg-indigo-500 px-3 py-1 text-xs text-white">Remove GRN</button></div><table className="mt-2 w-full"><thead><tr>{['GRN Code','Inv No','SKU Code','Recvd','Invoice Qty','Invoice Cost','Document Amt'].map(x=><Th key={x}>{x}</Th>)}</tr></thead></table></div>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
  const reset=()=>setFilters({invoice:'',vendor:'',date:'',posting:'',name:'',status:''});return <Shell active="procurement" breadcrumb="Procurement > Vendor Invoice > Vendor Invoice Enquiry" openScreens={[{label:'Vendor Invoice Enquiry',to:'#'}]}><TopActions onSearch={()=>{}} onReset={reset} onAdd={()=>setEditing(true)} onExport={()=>{}}/><table className="w-full bg-white"><thead><tr>{['Invoice Number','Vendor Code','Invoice Date','Posting Date','Vendor Name','Inv Amt','Status'].map(x=><Th key={x}>{x}</Th>)}</tr><tr>{Object.keys(filters).map(k=><th key={k} className="p-1"><input className="w-full border p-1 text-xs" value={(filters as any)[k]} onChange={e=>setFilters({...filters,[k]:e.target.value})}/></th>)}</tr></thead><tbody>{filtered.map(r=><tr key={r.id}><Td>{r.document_invoice_no}</Td><Td>{r.vendor_code}</Td><Td>{r.invoice_date}</Td><Td>{r.posting_date}</Td><Td>{r.vendor_name}</Td><Td>{Number(r.invoice_amount).toFixed(2)}</Td><Td><Status value={r.status}/></Td></tr>)}</tbody></table>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
}

export function OTBManagement() {
  const { locations } = useActiveLocations();
  const {requestDownload}=useDownload();const [rows,setRows]=useState<any[]>([]);const [editing,setEditing]=useState(false);const [tree,setTree]=useState(false);const [notice,setNotice]=useState<Notice>(null);const [filters,setFilters]=useState({id:'',description:'',location:'',start:'',end:'',status:''});
  const blank={description:'',location:'',vendor_code:'',start_date:'',end_date:'',operand_type:'Category',operand:'',total_budget:''};const [form,setForm]=useState(blank);const load=()=>apiGet<any[]>('/api/procurement?entity=otb').then(setRows);useEffect(()=>{void load()},[]);const filtered=rows.filter(r=>(!filters.id||r.otb_id.includes(filters.id))&&(!filters.description||r.description.toLowerCase().includes(filters.description.toLowerCase()))&&(!filters.location||String(r.location).includes(filters.location))&&(!filters.start||r.start_date===filters.start)&&(!filters.end||r.end_date===filters.end)&&(!filters.status||r.status===filters.status));
  const save=async()=>{try{const row=await apiSend('/api/procurement?entity=otb','POST',{entity:'otb',...form,total_budget:Number(form.total_budget)});setNotice({msg:'OTB saved successfully.',type:'ok'});setEditing(false);setForm(blank);load();return row}catch(e:any){setNotice({msg:e.message,type:'err'})}};const confirm=async()=>{const row:any=await save();if(row){await apiSend('/api/procurement','PUT',{entity:'otb',id:row.id,action:'confirm'});setNotice({msg:'OTB confirmed successfully.',type:'ok'});load()}};
  if(editing)return <Shell active="procurement" breadcrumb="Procurement > OTB View/Edit" openScreens={[{label:'OTB Enquiry',to:'#'},{label:'View/Edit OTB',to:'#'}]}><div className="border bg-white"><div className="flex justify-end gap-2 p-2"><Btn variant="warn" onClick={save}>Save</Btn><Btn onClick={confirm}>Confirm</Btn><Btn variant="ghost" onClick={()=>setEditing(false)}>Cancel</Btn><Btn variant="ghost" onClick={()=>setForm(blank)}>Reset</Btn><Btn variant="ghost" onClick={()=>setForm(blank)}>Add New</Btn></div><div className="grid grid-cols-3 gap-x-12 gap-y-3 border-t p-5"><Field label="OTB ID"><input disabled className="ci bg-slate-100"/></Field><Field label="Start Date" required><input type="date" className="ci" value={form.start_date} onChange={e=>setForm({...form,start_date:e.target.value})}/></Field><Field label="Total Budget"><span className="font-semibold">{Number(form.total_budget||0).toFixed(2)}</span></Field><Field label="Description" required><input className="ci" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="End Date" required><input type="date" className="ci" value={form.end_date} onChange={e=>setForm({...form,end_date:e.target.value})}/></Field><Field label="Consumed"><span>0.00</span></Field><Field label="Location" required><select className="ci" value={form.location} onChange={e=>setForm({...form,location:e.target.value})}><option value="">Select active location</option>{locations.map(location=><option key={location.location_code} value={location.location_name}>{location.location_name} ({location.location_code})</option>)}</select></Field><Field label="Status"><Status value="Pending"/></Field><Field label="Open To Buy"><span>{Number(form.total_budget||0).toFixed(2)}</span></Field><Field label="Vendor Code"><input className="ci" value={form.vendor_code} onChange={e=>setForm({...form,vendor_code:e.target.value})}/></Field><Field label="Operand Type"><select className="ci" value={form.operand_type} onChange={e=>setForm({...form,operand_type:e.target.value})}><option>Category</option><option>Vendor</option><option>Brand</option></select></Field></div><fieldset className="m-4 border p-3"><legend className="px-2 text-sm text-slate-500">OTB Detail</legend><div className="flex items-center gap-3"><label className="text-xs">Operand</label><button onClick={()=>setTree(true)} className="ci max-w-60 text-left">{form.operand||'Select...'}</button><label className="text-xs">Total Budget</label><input type="number" className="ci max-w-60" value={form.total_budget} onChange={e=>setForm({...form,total_budget:e.target.value})}/><button className="bg-sky-600 px-3 py-2 text-xs text-white">Add</button><button className="border px-3 py-2 text-xs">Remove</button></div><table className="mt-3 w-full"><thead><tr>{['Operand','Total Budget','Consumed','Remaining','Updated By','Updated Date'].map(x=><Th key={x}>{x}</Th>)}</tr></thead>{form.operand&&<tbody><tr><Td>{form.operand}</Td><Td>{Number(form.total_budget||0).toFixed(2)}</Td><Td>0.00</Td><Td>{Number(form.total_budget||0).toFixed(2)}</Td><Td>super admin</Td><Td>{new Date().toISOString().slice(0,10)}</Td></tr></tbody>}</table></fieldset></div><Modal title="Merchandising Hierarchy Pick List" open={tree} onClose={()=>setTree(false)}><div className="max-h-80 overflow-auto text-sm">{['Apparel','Books','Electronics','Footwear','Healthcare','Home & Living','media','Sports','Watches'].map(x=><label key={x} className="block py-1"><input type="radio" name="operand" checked={form.operand===x} onChange={()=>setForm({...form,operand:x})}/> ⊞ {x}</label>)}</div><div className="mt-3 flex justify-end gap-2"><Btn onClick={()=>setTree(false)}>OK</Btn><Btn variant="ghost" onClick={()=>setTree(false)}>Close</Btn></div></Modal>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
  const reset=()=>setFilters({id:'',description:'',location:'',start:'',end:'',status:''});return <Shell active="procurement" breadcrumb="Procurement > OTB Enquiry" openScreens={[{label:'OTB Enquiry',to:'#'}]}><TopActions onSearch={()=>{}} onReset={reset} onAdd={()=>setEditing(true)} onExport={()=>requestDownload({title:'OTB Enquiry',module:'otb',baseName:'otb-enquiry',data:{columns:['OTB ID','Description','Location','Start Date','End Date','Status','Total Budget','Consumed','OpenToBuy'],rows:filtered.map(r=>[r.otb_id,r.description,r.location,r.start_date,r.end_date,r.status,r.total_budget,r.consumed,r.open_to_buy])}})}/><table className="w-full bg-white"><thead><tr>{['OTB ID','Description','Location','Start Date','End Date','Status','Total Budget','Consumed','OpenToBuy'].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody>{filtered.map(r=><tr key={r.id}><Td>{r.otb_id}</Td><Td>{r.description}</Td><Td>{r.location}</Td><Td>{r.start_date}</Td><Td>{r.end_date}</Td><Td><Status value={r.status}/></Td><Td>{Number(r.total_budget).toFixed(2)}</Td><Td>{Number(r.consumed).toFixed(2)}</Td><Td>{Number(r.open_to_buy).toFixed(2)}</Td></tr>)}</tbody></table>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
}

export function BackOrderPO() {
  const {requestDownload}=useDownload();
  const blank={siteLocation:'',skuCode:'',vendorCode:'',merchCodes:'',fromOrderDate:'',toOrderDate:'',brandCode:'',priorityCode:'-1',pendingConfirm:false,orderHold:'0',channelCode:'-1',backOrder:false,refVal:'',orderTags:[] as string[],orderTypes:[] as string[],fromExpDelDate:'',toExpDelDate:'',page:1,rows:20};
  const [filters,setFilters]=useState(blank); const [data,setData]=useState<{rows:any[],records:number,total:number,page:number}>({rows:[],records:0,total:0,page:0}); const [notice,setNotice]=useState<Notice>(null); const [advanced,setAdvanced]=useState(false); const [busy,setBusy]=useState(false); const [editing,setEditing]=useState<{id:number;field:'unitCost'|'toOrderQty';value:string}|null>(null); const [orderTypeOptions,setOrderTypeOptions]=useState<string[]>([]);
  const search=async(page=filters.page)=>{setBusy(true);try{const result=await apiSend<any>('/api/back-orders?action=search','POST',{...filters,page});setData(result);setOrderTypeOptions(result.orderTypeOptions||[]);setFilters({...filters,page:result.page});setEditing(null)}catch(e:any){setNotice({msg:e.message,type:'err'})}finally{setBusy(false)}};
  const startEdit = (row:any, field:'unitCost'|'toOrderQty') => setEditing({id:row.id,field,value:String(row[field] ?? '')});
  const saveEdit = async () => {
    if (!editing) return;
    const value = Number(editing.value);
    if (!editing.value.trim() || !Number.isFinite(value) || (editing.field === 'unitCost' ? value < 0 : value <= 0)) {
      setNotice({msg:editing.field === 'unitCost' ? 'Unit Cost must be zero or greater.' : 'To Order Qty must be greater than zero.',type:'err'});
      return;
    }
    setBusy(true);
    try {
      const saved = await apiSend<any>('/api/back-orders','PUT',{id:editing.id,[editing.field]:value});
      setData(current => ({...current,rows:current.rows.map(row => row.id === saved.id ? saved : row)}));
      setEditing(null);
    } catch (error:any) { setNotice({msg:error.message,type:'err'}); }
    finally { setBusy(false); }
  };
  const planningCell = (row:any, field:'unitCost'|'toOrderQty') => {
    const activeEdit = editing;
    if (activeEdit && activeEdit.id === row.id && activeEdit.field === field) return <span className="flex items-center gap-1">
      <input aria-label={'Edit ' + field + ' for ' + row.skuCode} autoFocus className="ci w-24" type="number" min={field === 'unitCost' ? '0' : '0.01'} step="any" value={activeEdit.value} onChange={event => setEditing(current => current ? {...current,value:event.target.value} : null)} onKeyDown={event => {if(event.key === 'Enter') void saveEdit(); if(event.key === 'Escape') setEditing(null)}} />
      <button type="button" disabled={busy} onClick={() => void saveEdit()}>Save</button>
      <button type="button" onClick={() => setEditing(null)}>Cancel</button>
    </span>;
    return <button type="button" disabled={busy || !!row.isProcessed} onClick={() => startEdit(row,field)}>{row[field] ?? '—'}</button>;
  };
  const download=()=>requestDownload({title:'PO From Back Orders — visible rows',module:'po-back-orders',baseName:'po-back-orders-visible-rows',data:{columns:['SKU Code','Vendor','MRP','Unit Cost','Suggested Qty','To Order Qty','Back Order Qty'],rows:data.rows.map(r=>[r.skuCode,r.vendorCode,r.mrp,r.unitCost,r.suggestOrderQty,r.toOrderQty,r.bckOdrQty])}});
  return <Shell active="procurement" breadcrumb="Procurement > PO Create/Edit > From Back Order" openScreens={[{label:'From Back Orders',to:'#'}]}><p className="mb-2 rounded border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-950">Stored back-order rows are legacy planning records. Their Inventory value is unavailable until each SKU and location is mapped to Central Inventory. Create PO is paused until one source row can create exactly one PO in a durable transaction. Download includes the visible page only.</p><div className="mb-2 flex justify-end gap-2"><Btn variant="warn" onClick={()=>search(1)} disabled={busy}>Search</Btn><Btn variant="ghost" onClick={()=>{setFilters(blank);setData({rows:[],records:0,total:0,page:0});setEditing(null)}}>Reset</Btn><Btn variant="ghost" onClick={()=>setAdvanced(!advanced)}>Advanced Search</Btn><Btn variant="ghost" onClick={download} disabled={!data.rows.length}>Download visible rows</Btn><Btn disabled title="PO generation requires an atomic source-row transaction">Create PO unavailable</Btn></div><div className="grid grid-cols-2 gap-3 border bg-white p-3 md:grid-cols-4"><label className="text-xs">Order Date<input className="ci mt-1 w-full" type="date" value={filters.fromOrderDate} onChange={e=>setFilters({...filters,fromOrderDate:e.target.value})}/></label><label className="text-xs">SKU Code<input className="ci mt-1 w-full" maxLength={50} value={filters.skuCode} onChange={e=>setFilters({...filters,skuCode:e.target.value})}/></label><label className="text-xs">Brand<input className="ci mt-1 w-full" value={filters.brandCode} onChange={e=>setFilters({...filters,brandCode:e.target.value})}/></label><label className="text-xs">Vendor<input className="ci mt-1 w-full" maxLength={20} value={filters.vendorCode} onChange={e=>setFilters({...filters,vendorCode:e.target.value})}/></label><label className="text-xs">Order Type<select multiple className="ci mt-1 h-20 w-full" value={filters.orderTypes} onChange={e=>setFilters({...filters,orderTypes:Array.from(e.target.selectedOptions,o=>o.value)})}>{orderTypeOptions.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Ship by date<input className="ci mt-1 w-full" type="date" value={filters.fromExpDelDate} onChange={e=>setFilters({...filters,fromExpDelDate:e.target.value})}/></label></div>{advanced&&<div className="mt-2 grid grid-cols-2 gap-3 border p-3 md:grid-cols-4"><label>Merchandising Hierarchy<input className="ci w-full" value={filters.merchCodes} onChange={e=>setFilters({...filters,merchCodes:e.target.value})}/></label><label>Priority<select className="ci w-full" value={filters.priorityCode} onChange={e=>setFilters({...filters,priorityCode:e.target.value})}><option value="-1">--- Select ---</option><option>High</option><option>Medium</option><option>Normal</option></select></label><label>Reference No<input className="ci w-full" value={filters.refVal} onChange={e=>setFilters({...filters,refVal:e.target.value})}/></label><label>Back Order<input type="checkbox" checked={filters.backOrder} onChange={e=>setFilters({...filters,backOrder:e.target.checked})}/></label></div>}<table className="mt-2 w-full bg-white"><thead><tr>{['SKU Code','Vendor','MRP','Unit Cost','suggested Qty','To Order Qty','Inventory','Back Order Qty','PO Qty','Pending STO Qty'].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody>{data.rows.length?data.rows.map(row=><tr key={row.id}><Td>{row.skuCode}<div>{row.skuDesc}</div></Td><Td>{row.vendorCode}</Td><Td>{row.mrp}</Td><Td>{planningCell(row,'unitCost')}</Td><Td>{row.suggestOrderQty}</Td><Td>{planningCell(row,'toOrderQty')}</Td><Td>{row.inventory_trust === "central-unmapped" ? "Unavailable" : row.inventory}</Td><Td>{row.bckOdrQty}</Td><Td>{row.poQty}</Td><Td>{row.pendingSTOQty}</Td></tr>):<tr><td colSpan={10} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr>}</tbody></table><div className="mt-2 flex justify-end gap-2 text-xs">Page {data.page} of {data.total}<select value={filters.rows} onChange={e=>setFilters({...filters,rows:Number(e.target.value)})}>{[20,50,100,200].map(x=><option key={x}>{x}</option>)}</select><Btn variant="ghost" disabled={data.page<=1} onClick={()=>search(data.page-1)}>Previous</Btn><Btn variant="ghost" disabled={!data.total||data.page>=data.total} onClick={()=>search(data.page+1)}>Next</Btn></div>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
}

function LegacyBackOrderPO() {
  const initial={orderDate:'',skuCode:'',brand:'',vendor:'',orderTypes:[] as string[],shipByDate:'',priority:'',orderHold:'',backOrder:false,merchandise:'',reference:'',channel:'',pendingConfirm:false,location:''};
  const [filters,setFilters]=useState(initial); const [searched,setSearched]=useState(false); const [advanced,setAdvanced]=useState(false); const [notice,setNotice]=useState<Notice>(null); const [picker,setPicker]=useState<'sku'|'brand'|'vendor'|'merchandise'|null>(null); const [orderTypePicker,setOrderTypePicker]=useState(false); const [pickQuery,setPickQuery]=useState(''); const [skus,setSkus]=useState<any[]>([]); const [vendors,setVendors]=useState<any[]>([]); const [purchaseOrders,setPurchaseOrders]=useState<any[]>([]); const [salesOrders,setSalesOrders]=useState<any[]>([]);
  useEffect(()=>{apiGet<any[]>('/api/skus').then(setSkus);apiGet<any[]>('/api/vendors').then(setVendors);apiGet<any[]>('/api/purchase-orders').then(setPurchaseOrders);apiGet<any[]>('/api/sale-orders').then(setSalesOrders)},[]);
  useEffect(()=>{
    if(!orderTypePicker)return;
    const toggle=(event:MouseEvent)=>{
      const label=(event.target as HTMLElement).closest('label');
      const input=label?.querySelector<HTMLInputElement>('input[type="checkbox"]');
      const type=label?.textContent?.trim()||'';
      if(!input||!orderTypes.includes(type))return;
      event.preventDefault();
      setFilters(current=>({...current,orderTypes:current.orderTypes.includes(type)?current.orderTypes.filter(value=>value!==type):[...current.orderTypes,type]}));
    };
    document.addEventListener('click',toggle,true);
    return()=>document.removeEventListener('click',toggle,true);
  },[orderTypePicker]);
  const reset=()=>{setFilters(initial);setSearched(false);setAdvanced(false)}; const brands=Array.from(new Set(skus.map(x=>x.brand||x.brand_name).filter(Boolean))); const merch=Array.from(new Set(skus.map(x=>x.category||x.category_name).filter(Boolean))); const locations=Array.from(new Set(purchaseOrders.map(x=>x.warehouse).filter(Boolean))); const channels=Array.from(new Set(salesOrders.map(x=>x.channel).filter(Boolean)));
  const choose=(value:string)=>{if(picker==='sku')setFilters({...filters,skuCode:value});if(picker==='brand')setFilters({...filters,brand:value});if(picker==='vendor')setFilters({...filters,vendor:value});if(picker==='merchandise')setFilters({...filters,merchandise:value});setPicker(null);setPickQuery('')}; const pickItems=picker==='sku'?skus.map(x=>x.sku_code||x.code).filter(Boolean):picker==='vendor'?vendors.map(x=>x.vendor_code||x.code).filter(Boolean):picker==='brand'?brands:merch;
  const orderTypes=['Inbound QC','abhbill','KitTo','Normal','ORDERTYPE2','Packaging Material','Return','TestDemo','tgeg','CASH','Cash On Delivery','B2BGC-COD','B2CGC-COD','BOPIS-COD','BOSS-COD','BOSSCOIN-COD','COD','EA-COD','ROPIS-COD','VAR_ORDERTYPE2','B2BGC-Prepaid','B2CGC-Prepaid','BOPIS-Prepaid','BOSS-Prepaid','BOSSCOIN-Prepaid','checkmo','Credit','Damage Return','Dispose','EA-Prepaid','JIT','MTSO','Normal Return','not defined','Prepaid','ROPIS-Prepaid','TransferTest','Not Defined','ONLINE','STOTEST'];
  return <Shell active="procurement" breadcrumb="Procurement > PO Create/Edit > From Back Order" openScreens={[{label:'From Back Orders',to:'#'}]}><div className="mb-2 flex justify-end gap-2"><Btn variant="warn" onClick={()=>setSearched(true)}>Search</Btn><Btn variant="ghost" onClick={reset}>Reset</Btn><Btn variant="ghost" onClick={()=>setAdvanced(!advanced)}>Advanced Search</Btn><Btn variant="ghost" onClick={()=>setNotice({msg:'No data found in the grid.',type:'err'})}>Download</Btn><Btn onClick={()=>setNotice({msg:'Please Select SKU To Create PO.',type:'err'})}>Create PO</Btn></div><div className="grid grid-cols-2 gap-3 border bg-white p-3 md:grid-cols-4"><label className="text-xs">Order Date<input id="orderdDate" className="ci mt-1 w-full" value={filters.orderDate} onChange={e=>setFilters({...filters,orderDate:e.target.value})}/></label>{[['sku','SKU Code','skuCode'],['brand','Brand','brand'],['vendor','Vendor','vendor']].map(([kind,label,key])=><label key={kind} className="text-xs">{label}<span className="flex"><input id={key==='brand'?'brandText':key==='vendor'?'vendorCode':'skuCode'} className="ci mt-1 w-full" value={(filters as any)[key]} onChange={e=>setFilters({...filters,[key]:e.target.value})}/><button type="button" className="mt-1 border px-2" onClick={()=>setPicker(kind as any)}>...</button></span></label>)}<label className="text-xs">Order Type<button id="orderTypeSelect" type="button" onClick={()=>setOrderTypePicker(true)} className="ci mt-1 flex h-9 w-full items-center justify-between text-left"><span className="truncate">{filters.orderTypes.length?filters.orderTypes.join(', '):'--- Select ---'}</span><span>⌄</span></button></label><label className="text-xs">Ship by date<input id="expDelDate" className="ci mt-1 w-full" value={filters.shipByDate} onChange={e=>setFilters({...filters,shipByDate:e.target.value})}/></label></div>{advanced&&<div id="poBackOrderFilters" className="mt-2 grid grid-cols-2 gap-3 border bg-slate-50 p-3 md:grid-cols-4"><label className="text-xs">Merchandising Hierarchy<span className="flex"><input id="merchId" className="ci mt-1 w-full" value={filters.merchandise} onChange={e=>setFilters({...filters,merchandise:e.target.value})}/><button id="merchPL" type="button" className="mt-1 border px-2" onClick={()=>setPicker('merchandise')}>...</button></span></label><label className="text-xs">Priority<select id="priority" className="ci mt-1 w-full" value={filters.priority} onChange={e=>setFilters({...filters,priority:e.target.value})}><option value="">--- Select ---</option><option>High</option><option>Medium</option><option>Normal</option></select></label><label className="text-xs">Location<select id="siteLocation" className="ci mt-1 w-full" value={filters.location} onChange={e=>setFilters({...filters,location:e.target.value})}><option value="">--- Select ---</option>{locations.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Channel<select id="channel" className="ci mt-1 w-full" value={filters.channel} onChange={e=>setFilters({...filters,channel:e.target.value})}><option value="">--- Select ---</option>{channels.map(x=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Reference No<input id="refVal" className="ci mt-1 w-full" value={filters.reference} onChange={e=>setFilters({...filters,reference:e.target.value})}/></label><label className="text-xs">Order Hold<select id="orderHold" className="ci mt-1 w-full" value={filters.orderHold} onChange={e=>setFilters({...filters,orderHold:e.target.value})}><option value="">--- Select ---</option><option>Yes</option><option>No</option></select></label><label className="flex items-center gap-2 text-xs"><input id="pendingConfirm" type="checkbox" checked={filters.pendingConfirm} onChange={e=>setFilters({...filters,pendingConfirm:e.target.checked})}/>Pending Confirmation</label><label className="flex items-center gap-2 text-xs"><input id="backOrder" type="checkbox" checked={filters.backOrder} onChange={e=>setFilters({...filters,backOrder:e.target.checked})}/>Back Order</label></div>}<p className="mt-2 text-xs text-emerald-600">** SKU Highlighted In Green Have Multiple Vendors.</p><table id="poBackOrderMaintGrid" className="mt-2 w-full bg-white"><thead><tr><Th><input aria-label="Select all SKU rows" type="checkbox" disabled/></Th>{['SKU Code','Vendor','MRP','Unit Cost','suggested Qty','To Order Qty','Inventory','Back Order Qty','PO Qty','Pending STO Qty'].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody><tr><td colSpan={11} className="p-5 text-center text-xs text-slate-400">No records to view</td></tr></tbody></table>{searched&&<div className="mt-2 text-right text-xs text-slate-500">Page of 0 <select><option>20</option><option>50</option><option>100</option><option>200</option></select></div>}<Modal title={picker==='vendor'?'Select Vendor':picker==='brand'?'Select Brand':picker==='sku'?'Select SKU':'Merchandising Hierarchy'} open={Boolean(picker)} onClose={()=>setPicker(null)}><input aria-label="Picker search" className="ci mb-2 w-full" value={pickQuery} onChange={e=>setPickQuery(e.target.value)} placeholder="Search"/><div className="max-h-64 overflow-auto border">{pickItems.filter(x=>String(x).toLowerCase().includes(pickQuery.toLowerCase())).map(x=><button key={x} type="button" onClick={()=>choose(String(x))} className="block w-full border-b px-3 py-2 text-left text-xs hover:bg-slate-50">{x}</button>)}</div><div className="mt-3 text-right"><Btn variant="ghost" onClick={()=>setPicker(null)}>Close</Btn></div></Modal><Modal title="Order Type" open={orderTypePicker} onClose={()=>setOrderTypePicker(false)}><div className="max-h-72 overflow-auto border">{orderTypes.map(type=><label key={type} className="flex cursor-pointer items-center gap-2 border-b px-3 py-2 text-xs"><input type="checkbox" checked={filters.orderTypes.includes(type)} onChange={e=>setFilters({...filters,orderTypes:e.target.checked?[...filters.orderTypes,type]:filters.orderTypes.filter(x=>x!==type)})}/>{type}</label>)}</div><div className="mt-3 flex justify-end gap-2"><Btn variant="ghost" onClick={()=>setFilters({...filters,orderTypes:[]})}>Clear</Btn><Btn onClick={()=>setOrderTypePicker(false)}>OK</Btn></div></Modal>{notice&&<Toast {...notice} onClose={()=>setNotice(null)}/>}</Shell>;
}
